<?php require_once __DIR__.'/../config/auth.php';require_role('kasir');$s=db()->prepare("SELECT t.*,u.name cashier,p.method,p.amount,p.change_amount FROM transactions t JOIN users u ON u.id=t.cashier_id JOIN payments p ON p.transaction_id=t.id WHERE t.invoice=? AND t.cashier_id=?");$s->execute([$_GET['id']??'',user()['id']]);$trx=$s->fetch();if(!$trx){http_response_code(404);exit('Transaksi tidak ditemukan atau belum dibayar.');}$d=db()->prepare("SELECT d.*,GROUP_CONCAT(dt.topping_name ORDER BY dt.id SEPARATOR ', ') toppings FROM transaction_details d LEFT JOIN transaction_detail_toppings dt ON dt.transaction_detail_id=d.id WHERE d.transaction_id=? GROUP BY d.id");$d->execute([$trx['id']]);$details=$d->fetchAll();$pageTitle='Detail Transaksi';$active='riwayat';include __DIR__.'/../includes/header.php';?>
<?php if(isset($_GET['success'])):?><div class="alert">Transaksi berhasil disimpan. Stok telah diperbarui.</div><?php endif;?><section class="card" style="max-width:680px;margin:auto"><div style="text-align:center"><div class="coffee-mark" style="width:58px;height:58px;font-size:27px;border-radius:17px;margin:0 auto 12px"><i class="bi bi-check-lg"></i></div><h2><?=e($trx['invoice'])?></h2><p class="muted"><?=date('d M Y, H:i',strtotime($trx['created_at']))?> · <?=e($trx['cashier'])?><?php if($trx['order_name']):?> · <?=e($trx['order_name'])?><?php endif;?><?php if($trx['table_number']):?> · Meja <?=e($trx['table_number'])?><?php endif;?></p></div><div class="table-wrap"><table class="table"><tbody><?php foreach($details as $detail):?><tr><td><?=e($detail['product_name'])?> × <?=$detail['quantity']?><?php if($detail['toppings']):?><br><small class="muted">+ <?=e($detail['toppings'])?></small><?php endif;?><?php if($detail['note']):?><br><small class="muted">Catatan: <?=e($detail['note'])?></small><?php endif;?></td><td style="text-align:right"><?=rupiah($detail['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="summary-row"><span>Subtotal</span><span><?=rupiah($trx['subtotal'])?></span></div><div class="summary-row"><span>Diskon</span><span>-<?=rupiah($trx['discount'])?></span></div><div class="summary-row total"><span>Total</span><span><?=rupiah($trx['total'])?></span></div><div class="summary-row"><span><?=ucfirst($trx['method'])?></span><span><?=rupiah($trx['amount'])?></span></div><div class="summary-row"><span>Kembalian</span><span><?=rupiah($trx['change_amount'])?></span></div><div class="actions no-print" style="margin-top:20px"><a class="btn primary" href="struk.php?id=<?=urlencode($trx['invoice'])?>" target="_blank"><i class="bi bi-printer"></i> Cetak struk</a><a class="btn soft" href="kasir.php">Transaksi baru</a></div></section><?php include __DIR__.'/../includes/footer.php';?>
